INSERT INTO monan (TenMon, MoTa, Gia, image_url, MaDM, IsAvailable, SoLuongDaBan, SoLuongTon, created_at, updated_at) VALUES (N'Pepsi', N'Nước ngọt có ga sảng khoái.', 12000, 'Pepsi.png', 5, 1, 630, 200, SYSDATE, SYSDATE);
